# Print keys at top level
def print_keys(obj, prefix=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(f'{prefix}{k}')
            if isinstance(v, dict):
                print_keys(v, prefix + '  ')
            elif isinstance(v, list) and len(v) > 0 and isinstance(v[0], dict):
                print_keys(v[0], prefix + '  ')

